def process(parse_sunspot_data) -> pd.DataFrame:
    df = parse_sunspot_data.copy()
    df['year_int'] = df['year'].astype(int)
    return df[(df['year_int'] >= 1960) & (df['year_int'] <= 2020)].reset_index(drop=True)

def process(detect_extrema) -> pd.DataFrame:
    maxima = detect_extrema[detect_extrema['type'] == 'maximum'].sort_values('year_int')
    minima = detect_extrema[detect_extrema['type'] == 'minimum'].sort_values('year_int')

    periods = []
    for i in range(len(maxima) - 1):
        period = maxima.iloc[i+1]['year_int'] - maxima.iloc[i]['year_int']
        periods.append(period)

    avg_period = sum(periods) / len(periods) if periods else 0

    return pd.DataFrame({
        'metric': ['average_period'],
        'value': [round(avg_period, 2)]
    })
